from pathlib import Path
p = Path('/src/libxml2/tree.c')
src = p.read_text()
anchor = 'if ((node->type == XML_ELEMENT_NODE) && (node->ns != NULL)) {'
pos = src.find(anchor)
print('anchor pos', pos)
if pos == -1:
    raise SystemExit('anchor not found')
# find end of this block by braces balance
brace = src.find('{', pos)
depth = 0
end = None
for i in range(brace, len(src)):
    if src[i] == '{':
        depth += 1
    elif src[i] == '}':
        depth -= 1
        if depth == 0:
            end = i+1
            break
if end is None:
    raise SystemExit('could not determine block end')
print('block start', brace, 'block end', end)
old_block = src[pos:end]
print('Old block length', len(old_block))
new_block = '''if ((node->type == XML_ELEMENT_NODE) && (node->ns != NULL)) {
        xmlNsPtr ns;

        ns = xmlSearchNs(doc, ret, node->ns->prefix);
        if (ns == NULL) {
            /*
             * Humm, we are copying an element whose namespace is defined
             * out of the new tree scope. Search it in the original tree
             * and add it at the top of the new tree.
             *
             * TODO: Searching the original tree seems unnecessary. We
             * already have a namespace URI.
             */
            xmlNsPtr srcNs = xmlSearchNs(node->doc, node, node->ns->prefix);
            if (srcNs != NULL) {
                xmlNodePtr root = ret;

                while (root->parent != NULL) root = root->parent;
                xmlChar* href_dup = xmlStrdup(srcNs->href);
                xmlChar* prefix_dup = xmlStrdup(srcNs->prefix);
                ret->ns = xmlNewNs(root, href_dup, prefix_dup);
            } else {
                ret->ns = xmlNewReconciledNs(doc, ret, node->ns);
            }
            if (ret->ns == NULL)
                goto error;
        } else {
            /*
             * reference the existing namespace definition in our own tree.
             */
            ret->ns = ns;
        }
    }'''
new_src = src[:pos] + new_block + src[end:]
p.write_text(new_src)
print('Patched tree.c block')

